changeSet.sql:
DO $body$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT conname FROM pg_constraint
        WHERE conrelid = 'roles'::regclass AND contype = 'c'
    LOOP
        EXECUTE 'ALTER TABLE roles DROP CONSTRAINT IF EXISTS ' || quote_ident(r.conname);
    END LOOP;
END $body$;

DO $body$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT conname FROM pg_constraint
        WHERE conrelid = 'role_permissions'::regclass
          AND contype IN ('u', 'p')
          AND conname NOT IN (
              SELECT conname FROM pg_constraint
              WHERE conrelid = 'role_permissions'::regclass AND contype = 'p'
          )
    LOOP
        EXECUTE 'ALTER TABLE role_permissions DROP CONSTRAINT IF EXISTS ' || quote_ident(r.conname);
    END LOOP;
END $body$;

ALTER TABLE role_permissions RENAME COLUMN role_type TO role_name;

ALTER TABLE role_permissions
    ADD CONSTRAINT uq_role_permissions_name_key UNIQUE (role_name, permission_key);

DO $body$
DECLARE r RECORD;
BEGIN
    FOR r IN
        SELECT conname FROM pg_constraint
        WHERE conrelid = 'role_permissions'::regclass AND contype = 'c'
    LOOP
        EXECUTE 'ALTER TABLE role_permissions DROP CONSTRAINT IF EXISTS ' || quote_ident(r.conname);
    END LOOP;
END $body$;
